'short.VERIFICATION_REJECTED':['Rejected','Reddedildi'],'short.NO_VERIFICATION':['Not verified','Doğrulanmadı'],'short.NO_ACTIONS_PROPOSED':['Nothing to review','İncelenecek yok'],'short.NO_MODEL_CONFIGURED':['No model','Model yok'],'short.READ_ONLY_POLICY':['Read-only','Salt okunur'],
'reason.NOT_EXECUTED':['This tool did not run in the selected scenario.','Bu araç seçilen senaryoda çalışmadı.'],
'reason.NO_FILE_PROFILE_FOR_EXAMPLE':['Profiling needs a file; the PostgreSQL example reports its own scenario results.','Profil çıkarma bir dosya gerektirir; PostgreSQL örneği kendi senaryo sonuçlarını raporlar.'],
'reason.SOURCE_QUALITY_FAILURE':['On purpose: the source failed its contract, so processing it would spread bad data downstream.','Bilerek: kaynak sözleşmeyi karşılamadı; işlemek hatalı veriyi aşağı akışa yayardı.'],'reason.NO_RETAINED_RUN':['No retained run exists to read.','Okunacak saklı bir çalıştırma yok.'],'reason.VERIFICATION_REJECTED':['The independent check rejected the evidence. Do not rely on this result.','Bağımsız kontrol kanıtı reddetti. Bu sonuca güvenmeyin.'],
'reason.NO_VERIFICATION':['No verification result is available.','Doğrulama sonucu yok.'],'reason.NO_ACTIONS_PROPOSED':['No findings, so there is nothing to approve.','Bulgu olmadığından onaylanacak bir şey yok.'],
'reason.NO_MODEL_CONFIGURED':['No language model is connected. This workspace does not guess causes; it shows observed patterns only.','Bağlı bir dil modeli yok. Bu çalışma alanı neden tahmin etmez; yalnızca gözlenen örüntüleri gösterir.'],'reason.READ_ONLY_POLICY':['This workspace never writes to source data. Repairs happen in your source system; then you inspect a fresh export.','Bu çalışma alanı kaynak veriye asla yazmaz. Düzeltmeler kaynak sisteminizde yapılır; sonra yeni dışa aktarımı incelersiniz.'],'panel.attn':['What needs attention','Dikkat gerektirenler'],'empty.attn.t':['Nothing to show yet','Henüz gösterilecek bir şey yok'],'empty.attn.x':['After an inspection, the most important findings appear here.','İncelemeden sonra en önemli bulgular burada görünür.'],
'cta.start':['Choose a source →','Kaynak seç →'],'cta.new':['New investigation','Yeni inceleme'],'attn.example':['Example scenario results are listed on the Investigations page.','Örnek senaryo sonuçları İncelemeler sayfasında listelenir.'],
'attn.pass':['No violations observed','İhlal gözlenmedi'],'attn.pass.x':['This describes the checks performed, not a guarantee about every possible issue.','Bu, yapılan kontrolleri tanımlar; olası her sorun için bir garanti değildir.'],
'attn.fail':['Records to review: {n}','{n} kaydın incelenmesi gerekiyor'],'attn.open':['Open the workspace →','Çalışma alanını aç →'],
'prio.1':['Fix first','Önce düzelt'],'prio.2':['Affects totals','Toplamları etkiler'],'prio.3':['Review','İncele'],
