'flow.d.claims':['Claims and Judge verdicts','İddialar ve hakem kararları'],'flow.d.claims.none':['No claim.','İddia yok.'],'flow.d.claims.wait':['Claims appear when the agent finishes and the record is sealed.','İddialar ajan bitince ve kayıt mühürlenince görünür.'],
