'rep.sum.evidence':['{records} readings from {from} to {to} were frozen as evidence (SHA-256 {digest}…).','{from} ile {to} arasındaki {records} okuma kanıt olarak donduruldu (SHA-256 {digest}…).'],
'rep.sum.noevidence':['No evidence window was frozen.','Kanıt penceresi dondurulmadı.'],
'rep.sum.norun':['No agent run was made on the evidence.','Kanıt üzerinde ajan çalışması yapılmadı.'],
'rep.sum.running':['The agent run is still in progress.','Ajan çalışması hâlâ sürüyor.'],
'rep.sum.runerror':['The agent run stopped without a record.','Ajan çalışması kayıt olmadan durdu.'],
'rep.sum.norecord':['The agent run finished, but its sealed record could not be read.','Ajan çalışması bitti, ancak mühürlü kaydı okunamadı.'],
'rep.sum.agents':['The agent run finished ({status}): of the candidates, the fixed probes support {s}, leave {o} open and refute {r}; the Judge accepted {accepted} claims, marked {advisory} advisory and rejected {rejected}.','Ajan çalışması bitti ({status}): sabit problar {s} adayı destekliyor, {o} adayı açık bırakıyor ve {r} adayı çürütüyor; Hakem {accepted} iddiayı kabul etti, {advisory} iddiayı danışma amaçlı işaretledi ve {rejected} iddiayı reddetti.'],
'rep.sum.decision.accepted':['{reviewer} accepted {candidate} as the working explanation on {at}: consistent with the fixed probes, not a root cause.','{reviewer}, {at} tarihinde {candidate} adayını çalışma açıklaması olarak kabul etti: sabit problarla tutarlı, kök neden değil.'],
'rep.sum.decision.rejected':['{reviewer} rejected every candidate on {at}.','{reviewer}, {at} tarihinde tüm adayları reddetti.'],
'rep.sum.decision.more_evidence':['{reviewer} asked for more evidence on {at}; the incident stays open for review.','{reviewer}, {at} tarihinde daha fazla kanıt istedi; olay inceleme için açık kalır.'],
