'qua.m.plant.wrong_supported':['A wrong mechanism supported','Yanlış bir mekanizma desteklendi'],'qua.m.plant.wrong_supported.x':['Frozen evidence on which the loop supports a mechanism that was not injected','Döngünün enjekte edilmemiş bir mekanizmayı desteklediği dondurulmuş kanıtlar'],
'qua.m.plant.false_alarms':['False alarms','Yanlış alarmlar'],'qua.m.plant.false_alarms.x':['Incidents opened by the plant with no fault injected','Arıza enjekte edilmemiş tesisin açtığı olaylar'],
