'qua.m.agents.a23_any':['Model lists the injected mechanism','Model enjekte edilen mekanizmayı listeliyor'],'qua.m.agents.a23_any.x':['A23 names it among its up to three suggestions','A23 onu en fazla üç önerisi arasında sayıyor'],
'qua.m.agents.a23_top1':['Model names it first','Model onu ilk sırada veriyor'],'qua.m.agents.a23_top1.x':['The first mechanism A23 lists is the injected one','A23’ün listelediği ilk mekanizma enjekte edilen mekanizma'],
'qua.m.agents.a23_misattributed':['Model misattributes an out-of-catalog change','Model katalog dışı bir değişikliği yanlış atfediyor'],'qua.m.agents.a23_misattributed.x':['Sign flip and seasonal amplitude changes for which A23 suggests a catalog mechanism','A23’ün katalog mekanizması önerdiği işaret dönmesi ve mevsimsel genlik değişiklikleri'],
'qua.m.agents.loop_sole':['Loop supports only the injected mechanism','Döngü yalnızca enjekte edilen mekanizmayı destekliyor'],'qua.m.agents.loop_sole.x':['The deterministic loop run by A24 on the same cases','Aynı vakalarda A24’ün çalıştırdığı deterministik döngü'],
'qua.m.agents.replay_fidelity':['Replay reproduces the live run','Yeniden oynatma canlı çalıştırmayı üretiyor'],'qua.m.agents.replay_fidelity.x':['Replayed run outcomes identical to the recorded live outcomes','Kaydedilmiş canlı sonuçlarla birebir aynı yeniden oynatma sonuçları'],
'qua.m.agents.run_p50_ms':['Median live run time','Ortanca canlı çalışma süresi'],'qua.m.agents.run_p50_ms.x':['Wall time of one whole 36-role investigation','36 rollü bir incelemenin tamamının duvar saati süresi'],
'qua.m.hypotheses.truth_sole_supported':['Only the injected mechanism supported','Yalnızca enjekte edilen mekanizma desteklendi'],'qua.m.hypotheses.truth_sole_supported.x':['Modelled cases where the loop supports the injected mechanism on its column and nothing else','Döngünün enjekte edilen mekanizmayı kendi sütununda destekleyip başka hiçbir şeyi desteklemediği modellenmiş vakalar'],
'qua.m.hypotheses.truth_supported':['Injected mechanism supported','Enjekte edilen mekanizma desteklendi'],'qua.m.hypotheses.truth_supported.x':['Whether or not another one is supported too','Başka biri de desteklensin ya da desteklenmesin'],
'qua.m.hypotheses.other_supported':['Another mechanism also supported','Başka bir mekanizma da desteklendi'],'qua.m.hypotheses.other_supported.x':['Modelled cases where a mechanism other than the injected one is supported as well','Enjekte edilenden başka bir mekanizmanın da desteklendiği modellenmiş vakalar'],
'qua.m.hypotheses.misattributed':['Out-of-catalog change misattributed','Katalog dışı değişiklik yanlış atfedildi'],'qua.m.hypotheses.misattributed.x':['Sign flip and seasonal amplitude changes for which the loop supports a catalog mechanism','Döngünün katalog mekanizması desteklediği işaret dönmesi ve mevsimsel genlik değişiklikleri'],
'qua.m.baseline.case_detection':['Injected change detected','Enjekte edilen değişiklik tespit edildi'],'qua.m.baseline.case_detection.x':['Cases in which every expected finding is raised','Beklenen her bulgunun üretildiği vakalar'],
