function tt(key,fallback){return STRINGS[key]?t(key):fallback;}
function t(key,params){
 // A count of exactly one uses the key's ".one" variant when there is one ("1 finding", not "1 findings").
 const entry=(params&&String(params.n)==='1'&&STRINGS[key+'.one'])||STRINGS[key];
 if(!entry)return key;
 const text=language==='tr'?entry[1]:entry[0];
 return params?text.replace(/\{(\w+)\}/g,(m,name)=>name in params?String(params[name]):m):text;
}
if(typeof module!=='undefined')module.exports={STRINGS};
